	public void testHashCollisionCollectionPreservesOtherLiteral(boolean collectFirst) throws Exception {
		IRI datatype = Values.iri("urn:refcount:collision-datatype");
		Literal[] literals = { Values.literal("long literal prefix plumless", datatype),
				Values.literal("long literal prefix buckeroo", datatype) };
		valueStore.startTransaction(true);
		long[] ids = { valueStore.storeValue(literals[0]), valueStore.storeValue(literals[1]) };
		valueStore.commit();
		int collected = collectFirst ? 0 : 1;
		valueStore.startTransaction(true);
		Set<Long> nextIds = new HashSet<>();
		valueStore.gcIds(Collections.singleton(ids[collected]), nextIds);
		assertTrue(nextIds.isEmpty());
		valueStore.commit();
		assertEquals("The other colliding literal keeps its forward mapping", ids[1 - collected],
				valueStore.getId(literals[1 - collected]));
		assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(literals[collected]));
		assertEquals(1L, persistedRefCount(valueStore.getId(datatype)));
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testRepeatedRetirementCannotDeleteReusedId(boolean tripleTerm) throws Exception {
		Value original = tripleTerm ? Values.tripleTerm(RDF.TYPE, RDF.TYPE, Values.literal(1))
				: Values.bnode("original");
		Value replacement = tripleTerm ? Values.tripleTerm(RDF.TYPE, RDF.TYPE, Values.literal(2))
				: Values.bnode("replacement");
		valueStore.startTransaction(true);
		long originalId = valueStore.storeValue(original);
		valueStore.commit();
		long firstRevision = valueStore.getRevision().getRevisionId();
		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(originalId), new HashSet<>());
		valueStore.commit();
		long laterRevision = valueStore.getRevision().getRevisionId();
		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(originalId), new HashSet<>());
		valueStore.commit();

		valueStore.unusedRevisionIds.add(firstRevision);
		valueStore.forceEvictionOfValues();
		valueStore.startTransaction(true);
		valueStore.commit();
		valueStore.startTransaction(true);
		long replacementId = valueStore.storeValue(replacement);
		assertEquals("The earlier retirement makes this ID available for reuse", originalId, replacementId);
		valueStore.commit();
		valueStore.unusedRevisionIds.add(laterRevision);
		valueStore.forceEvictionOfValues();
		valueStore.startTransaction(true);
		valueStore.commit();
		assertEquals("A later duplicate retirement must not remove the new owner", replacement,
				valueStore.getValue(replacementId));
	}

	@Test
	public void testLegacyCountsRebuiltFromActiveNestedTerms() throws Exception {
		IRI shared = Values.iri("urn:refcount:legacy-shared");
		TripleTerm inner = Values.tripleTerm(shared, shared, shared);
		valueStore.startTransaction(true);
		long innerId = valueStore.storeValue(inner);
		valueStore.storeValue(Values.tripleTerm(shared, shared, inner));
		Literal inlineObject = Values.literal(1);
		valueStore.storeValue(Values.tripleTerm(shared, shared, inlineObject));
		long inlineId = valueStore.getId(inlineObject);
		assertTrue("The fixture must exercise an inlined component", ValueIds.isInlined(inlineId));
		long retiredId = valueStore.storeValue(Values.tripleTerm(Values.bnode("retired"), shared, inner));
		valueStore.commit();
		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(retiredId), new HashSet<>());
		valueStore.commit();
		long sharedId = valueStore.getId(shared);
		replaceLegacyRefCount(sharedId, 1);

		valueStore.close();
		valueStore = createValueStore();
		assertEquals("Duplicate component roles count separately, retired terms do not", 7L,
				persistedRefCount(sharedId));
		assertEquals("The active outer term references its inner term", 1L, persistedRefCount(innerId));
		assertEquals("Inlined components do not require a dictionary record", 1L, persistedRefCount(inlineId));
		assertNull(valueStore.getValue(retiredId));
	}

	private long persistedRefCount(long id) throws IOException {
		return valueStore.writeTransaction((stack, txn) -> {
			int countsDbi = openDatabaseWithTxn(txn, "ref_counts", 0);
			MDBVal key = MDBVal.calloc(stack);
			key.mv_data(valueStore.id2data(valueStore.idBuffer(stack), id).flip());
			MDBVal data = MDBVal.calloc(stack);
			return mdb_get(txn, countsDbi, key, data) == MDB_SUCCESS ? Varint.readUnsigned(data.mv_data()) : 0L;
		});
	}

	@Test
	public void testDamagedLegacyReferencesFailBeforeReclamation() throws Exception {
		IRI datatype = Values.iri("urn:refcount:missing-datatype");
		valueStore.startTransaction(true);
		long literalId = valueStore.storeValue(Values.literal("surviving literal", datatype));
		valueStore.commit();
		long datatypeId = valueStore.getId(datatype);
		replaceLegacyRefCount(datatypeId, 0);
		valueStore.startTransaction(true);
		valueStore.gcIds(Collections.singleton(datatypeId), new HashSet<>());
		valueStore.commit();
		assertNotNull("The retired record remains recoverable before opening", valueStore.getData(datatypeId));
		valueStore.close();

		for (int attempt = 0; attempt < 3; attempt++) {
			IOException failure = assertThrows(IOException.class, this::createValueStore);
			assertTrue(failure.getMessage(), failure.getMessage().contains("missing or retired"));
			inspectNativeStore(new File(dataDir, "values"), (stack, txn) -> {
				assertNativeRecordExists(stack, txn, datatypeId);
				assertNativeRecordExists(stack, txn, literalId);
				assertEquals(0L, nativeRefCount(stack, txn, datatypeId));
				assertMigrationMarkerAbsent(stack, txn);
				MDBStat stat = MDBStat.calloc(stack);
				E(mdb_stat(txn, openDatabaseWithTxn(txn, "unused_ids", 0), stat));
				assertEquals("Failed validation must retain the pending retired datatype", 1L, stat.ms_entries());
				return null;
			});
		}
	}

	@Test
	public void testLegacyRebuildMapFullAbortsAndRetriesAfterGrowth() throws Exception {
		valueStore.close();
		File constrainedDir = new File(dataDir, "constrained");
		LmdbStoreConfig config = new LmdbStoreConfig().setValueDBSize(1024 * 1024).setAutoGrow(false);
		valueStore = new ValueStore(constrainedDir, config);
		valueStore.startTransaction(true);
		long datatypeId = 0;
		for (int i = 0; i < 1024; i++) {
			IRI datatype = Values.iri("urn:legacy:namespace:" + i + ":datatype");
			valueStore.storeValue(Values.literal("stored literal " + i, datatype));
			datatypeId = valueStore.getId(datatype);
		}
		valueStore.commit();
		replaceLegacyRefCount(datatypeId, 17);
		// Consume capacity independently of dictionary insertion so this fixture exercises the rebuild's ordinary puts.
		int capacityDbi = valueStore.writeTransaction(
				(stack, txn) -> openDatabaseWithTxn(txn, "migration_capacity", MDB_CREATE));
		for (int filler = 0;; filler++) {
			int entry = filler;
			try {
				valueStore.writeTransaction((stack, txn) -> {
					MDBVal key = MDBVal.calloc(stack);
					key.mv_data(stack.malloc(Integer.BYTES).putInt(entry).flip());
					MDBVal data = MDBVal.calloc(stack);
					data.mv_data(stack.calloc(2048));
					E(mdb_put(txn, capacityDbi, key, data, 0));
					return null;
				});
			} catch (IOException full) {
				assertTrue(full.getMessage(), full.getMessage().contains("MDB_MAP_FULL"));
				break;
			}
		}
		valueStore.close();
		IOException failure = assertThrows(IOException.class, () -> new ValueStore(constrainedDir, config).close());
		assertTrue(failure.getMessage(),
				failure.getMessage().contains("Insufficient space to rebuild LMDB reference counts atomically"));
		long lastDatatypeId = datatypeId;
		inspectNativeStore(constrainedDir, (stack, txn) -> {
			assertEquals("A failed rebuild must preserve the old count", 17L,
					nativeRefCount(stack, txn, lastDatatypeId));
			assertMigrationMarkerAbsent(stack, txn);
			return null;
		});

		valueStore = new ValueStore(constrainedDir, config.setAutoGrow(true));
		assertEquals("Growth must retry and commit the complete reconstruction", 1L, persistedRefCount(datatypeId));
	}

