	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	public void testInterruptedTripleTermIteratorReturnsReaderPermit(boolean rangeSearch) throws Exception {
		valueStore.startTransaction(true);
		long subjectId = valueStore.storeValue(RDF.TYPE);
		valueStore.commit();

		TxnManager txnManager = valueStore.getTxnManager();
		var lockManager = txnManager.lockManager();
		List<Txn> heldReaders = new ArrayList<>();
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Thread reader = new Thread(() -> {
			try (RecordIterator ignored = valueStore.getTripleTerms(rangeSearch ? subjectId : -1, -1, -1)) {
				Assert.fail("Iterator construction should be interrupted while waiting for the read lock");
			} catch (Throwable t) {
				failure.set(t);
			}
		}, "interrupted-triple-term-reader");
		long writeStamp = 0;
		try {
			// Leave exactly one permit for the constructor that will be interrupted.
			for (int i = 0; i < TxnManager.POOL_SIZE - 2; i++) {
				heldReaders.add(txnManager.createReadTxn());
			}
			writeStamp = lockManager.writeLock();
			reader.start();

			long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
			while (!lockManager.isReaderActive()) {
				assertTrue("Iterator constructor should reach the read lock: " + failure.get(), reader.isAlive());
				assertTrue("Iterator constructor should reach the read lock", System.nanoTime() < deadline);
				Thread.onSpinWait();
			}
			reader.interrupt();
			reader.join(TimeUnit.SECONDS.toMillis(5));
			assertFalse("Interrupted iterator constructor should terminate", reader.isAlive());
			SailException exception = assertInstanceOf(SailException.class, failure.get());
			assertInstanceOf(InterruptedException.class, exception.getCause());

			lockManager.unlockWrite(writeStamp);
			writeStamp = 0;
			assertTimeoutPreemptively(Duration.ofSeconds(5), () -> {
				try (RecordIterator iterator = valueStore.getTripleTerms(rangeSearch ? subjectId : -1, -1, -1)) {
					assertNull(iterator.next());
				}
			}, "Failed construction must return its reader permit for the next iterator");
		} finally {
			if (writeStamp != 0) {
				lockManager.unlockWrite(writeStamp);
			}
			reader.interrupt();
			reader.join(TimeUnit.SECONDS.toMillis(5));
			heldReaders.forEach(Txn::close);
		}
	}

	@Test
	public void testNextIdCorrectlyIncrements() throws Exception {
		valueStore.startTransaction(true);
		long lastId = 0;
		for (int i = 0; i < 10; i++) {
			lastId = valueStore.storeValue(Values.iri("some:iri" + i));
		}
		valueStore.commit();

		valueStore.close();
		valueStore = createValueStore();

		long id = valueStore.storeValue(Values.iri("some:new"));
		// value of the next ID should be one greater than the last ID stored before closing the store
		assertEquals(ValueIds.getValue(lastId) + 1, ValueIds.getValue(id));

		lastId = id;
		id = valueStore.storeValue(SimpleValueFactory.getInstance()
				.createTripleTerm(Values.iri("some:new"),
						Values.iri("some:new1"), Values.iri("some:new2")));
		assertEquals(ValueIds.getValue(lastId) + 3, ValueIds.getValue(id));

		lastId = id;
		valueStore.close();
		valueStore = createValueStore();

		id = valueStore.storeValue(Values.iri("some:new3"));
		// value of the next ID should be one greater than the last ID stored before closing the store
		assertEquals(ValueIds.getValue(lastId) + 1, ValueIds.getValue(id));
	}

	private long storeValueAndReopen(Value value, LmdbStoreConfig config) throws Exception {
		valueStore.close();
		valueStore = createValueStore(config);

		long id;
		valueStore.startTransaction(true);
		id = valueStore.storeValue(value);
		valueStore.commit();
		reopenValueStore(config);
		return id;
	}

	private void reopenValueStore(LmdbStoreConfig config) throws Exception {
		valueStore.close();
		valueStore = createValueStore(config);
	}

	private boolean isInitialized(Object value) throws Exception {
		Field initializedField = value.getClass().getDeclaredField("initialized");
		initializedField.setAccessible(true);
		return initializedField.getBoolean(value);
	}

